#define main historical_main
#include "../floydwarshall-cuda/main.cu"
#undef main
#include <vector>
#include <algorithm>
#include <cstdint>
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
constexpr unsigned INF=1000000;
std::vector<unsigned> dijkstra(std::vector<unsigned>&a,int n){std::vector<unsigned>out;for(int s=0;s<n;s++){std::vector<long long>d(n,INF);std::vector<bool>used(n);d[s]=0;for(int step=0;step<n;step++){long long best=INF;int node=-1;for(int i=0;i<n;i++)if(!used[i]&&d[i]<best){best=d[i];node=i;}if(node<0)break;used[node]=true;for(int j=0;j<n;j++)d[j]=std::min(d[j],best+a[node*n+j]);}for(auto v:d)out.push_back(v);}return out;}
bool route_rec(int i,int j,int depth,std::vector<unsigned>&p,int n,std::vector<int>&out){if(depth>2*n)return false;if(i==j){out.push_back(i);return true;}int k=p[i*n+j];if(k==i){out.push_back(i);out.push_back(j);return true;}if(k==j)return false;std::vector<int>left,right;if(!route_rec(i,k,depth+1,p,n,left)||!route_rec(k,j,depth+1,p,n,right))return false;out=left;out.insert(out.end(),right.begin()+1,right.end());return true;}
bool routes(std::vector<unsigned>&a,std::vector<unsigned>&d,std::vector<unsigned>&p,int n){for(int i=0;i<n;i++){if(d[i*n+i])return false;for(int j=0;j<n;j++){if(d[i*n+j]<INF){std::vector<int>path;if(!route_rec(i,j,0,p,n,path))return false;uint64_t cost=0;for(int q=0;q+1<(int)path.size();q++)cost+=a[path[q]*n+path[q+1]];if(cost!=d[i*n+j])return false;}for(int k=0;k<n;k++)if(uint64_t(d[i*n+j])>uint64_t(d[i*n+k])+d[k*n+j])return false;}}return true;}
struct Case{std::vector<unsigned>input,initial,expected,path;unsigned*d,*p;};
int main(int argc,char**argv){if(argc>1&&atoi(argv[1])!=1)return 2;int n=64;std::vector<Case>cases;std::vector<unsigned>prefix;for(int kind=0;kind<2;kind++){Case c;c.input.resize(n*n);c.initial.resize(n*n);srand(2);for(int i=0;i<n;i++)for(int j=0;j<n;j++){unsigned v;if(!kind)v=rand()%201;else{v=INF;int delta=(j-i)%32;if(i/32==j/32&&i!=j&&(delta==1||delta==3||delta==7||(i*17+j*13)%11==0))v=(i*7+j*11)%31+1;}if(i==j)v=0;c.input[i*n+j]=v;c.initial[i*n+j]=i;}c.expected=c.input;c.path=c.initial;floydWarshallCPUReference(c.expected.data(),c.path.data(),n);if(c.expected!=dijkstra(c.input,n)||!routes(c.input,c.expected,c.path,n))return 3;prefix.insert(prefix.end(),c.input.begin(),c.input.end());prefix.insert(prefix.end(),c.initial.begin(),c.initial.end());CK(cudaMalloc(&c.d,n*n*4));CK(cudaMalloc(&c.p,n*n*4));CK(cudaMemcpy(c.d,c.input.data(),n*n*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(c.p,c.initial.data(),n*n*4,cudaMemcpyHostToDevice));for(int k=0;k<n;k++)floydWarshallPass<<<dim3(4,4),dim3(16,16)>>>(c.d,c.p,n,k);cases.push_back(c);}CK(cudaDeviceSynchronize());bool allok=true;for(int trial=1;trial<=5;trial++){auto output=prefix;double seconds=0;bool ok=true;for(auto&c:cases){CK(cudaMemcpy(c.d,c.input.data(),n*n*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(c.p,c.initial.data(),n*n*4,cudaMemcpyHostToDevice));CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int k=0;k<n;k++)floydWarshallPass<<<dim3(4,4),dim3(16,16)>>>(c.d,c.p,n,k);CK(cudaDeviceSynchronize());seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();std::vector<unsigned>got(n*n),gp(n*n);CK(cudaMemcpy(got.data(),c.d,n*n*4,cudaMemcpyDeviceToHost));CK(cudaMemcpy(gp.data(),c.p,n*n*4,cudaMemcpyDeviceToHost));ok&=got==c.expected&&gp==c.path&&routes(c.input,got,gp,n);output.insert(output.end(),got.begin(),got.end());output.insert(output.end(),gp.begin(),gp.end());}allok&=ok;char file[80];sprintf(file,"floyd_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(output.data(),4,output.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"computed_output_values\":16384,\"input_prefix_values\":16384,\"max_abs_error\":0,\"max_rel_error\":0,\"timing_region\":\"sum_two_complete64pass_APSP_distance_and_intermediate_matrices\",\"jit_excluded\":true,\"internal_repeats\":1,\"route_reconstruction_pass\":%s,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",output.size(),ok?"true":"false",file,output.size());}for(auto&c:cases){CK(cudaFree(c.d));CK(cudaFree(c.p));}puts(allok?"PASS":"FAIL");return allok?0:1;}
